function CERTIFY(a, b, c, R):
  if a>0 and b>0 and c>0: return (BOUNDED, c/a + c/b)
  if a*b < 0:
    t <- sqrt(|R| + 1)
    x <- sqrt(t^2 + |c|); y <- t
    return (UNBOUNDED, (x, y))
  return (DEGENERATE, none)
